// Worker entry: the OpenNext-generated app, plus a cron handler, the image-job queue consumer,
// and the Claude connector (src/mcp), which answers on its own host and a few app paths.
// See https://opennext.js.org/cloudflare/howtos/custom-worker

// Generated by `opennextjs-cloudflare build`, so it may not exist when type-checking.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as app } from "./.open-next/worker.js";
import { connectorFetch, type AppFetch } from "./src/mcp";

declare global {
  var __sweepTokens: Set<string> | undefined;
  var __jobTokens: Set<string> | undefined;
}

/**
 * Calls one of the app's internal routes in-process, so it runs with the normal request
 * context (env, D1). The one-off token proves the call came from here; it never leaves
 * this isolate.
 */
async function internal(
  path: string,
  tokens: Set<string>,
  header: string,
  env: CloudflareEnv,
  ctx: ExecutionContext,
  body?: unknown,
) {
  const token = crypto.randomUUID();
  tokens.add(token);
  try {
    const res: Response = await app.fetch(
      new Request(`https://internal.invalid${path}`, {
        method: "POST",
        headers: { [header]: token, "content-type": "application/json" },
        body: body === undefined ? undefined : JSON.stringify(body),
      }),
      env,
      ctx,
    );
    const text = await res.text();
    if (!res.ok) throw new Error(`${path} failed (${res.status}): ${text}`);
    return text;
  } finally {
    tokens.delete(token);
  }
}

export default {
  async fetch(request, env, ctx) {
    return (await connectorFetch(app.fetch as AppFetch, request, env, ctx)) ?? app.fetch(request, env, ctx);
  },

  /** Every minute: finish generations and fal jobs whose tab was closed (see src/app/api/cron/sweep). */
  async scheduled(_controller, env, ctx) {
    console.log(
      "sweep",
      await internal("/api/cron/sweep", (globalThis.__sweepTokens ??= new Set()), "x-sweep-token", env, ctx),
    );
  },

  /**
   * Image jobs (see src/lib/images.ts). One per message; a consumer gets 15 minutes, more than
   * ArgoLink's 10-minute image timeout. Never retried: the job itself records failures, and a
   * second run could bill twice.
   */
  async queue(batch, env, ctx) {
    for (const message of batch.messages) {
      await internal(
        "/api/images/run",
        (globalThis.__jobTokens ??= new Set()),
        "x-job-token",
        env,
        ctx,
        message.body,
      ).catch((e) => console.error("image job", e));
      message.ack();
    }
  },
} satisfies ExportedHandler<CloudflareEnv>;
